#include "../../models/film_three_finger_resume/IsolatedContactTransfer.h"
#include <fstream>
#include <iostream>
#include <iomanip>
using namespace regrip_three_resume;
int main(int argc,char**argv){try{
 if(argc!=4)throw std::runtime_error("checkpoint,original independent states,metrics required");std::ifstream in(argv[1]);std::string magic,token;double time,h;unsigned step;in>>magic>>time>>h>>step>>token;SharedFilmSystem s(Layout(),{0,0,-.001},true,true);s.exactUnresolved=true;unsigned n=s.initial.size(),nf=s.shared.nf;Eigen::VectorXd q(n),v(n);for(double&x:q)in>>x;for(double&x:v)in>>x;double unused;for(unsigned i=0;i<4;++i)in>>unused;s.shared.M.setZero();for(unsigned f=0;f<3;++f){auto&m=s.shared.films[f].film;for(unsigned i=0;i<m.mass.size();++i){double mass;in>>mass;m.mass[i]=mass;for(unsigned d=0;d<3;++d){unsigned a=3*i+d;if(m.index[a]>=0)s.shared.M(f*nf+m.index[a],f*nf+m.index[a])+=mass*m.weight[a]*m.weight[a];}}}for(unsigned i=0;i<6;++i)for(unsigned j=0;j<6;++j)in>>s.shared.M(3*nf+i,3*nf+j);if(!in)throw std::runtime_error("checkpoint missing");auto result=isolatedContactTransfer(s,q,v,time,h);
 std::ifstream ref(argv[2]);std::string marker;double event,end;Eigen::VectorXd eq(n),ev(n),ep(n),fq(n),fv(n);ref>>marker>>event;for(auto*z:{&eq,&ev,&ep})for(double&x:*z)ref>>x;ref>>marker>>end;for(auto*z:{&fq,&fv})for(double&x:*z)ref>>x;if(!ref)throw std::runtime_error("original independent reference incomplete");double error=std::max({(result.pre.q-eq).cwiseAbs().maxCoeff(),(result.pre.v-ev).cwiseAbs().maxCoeff(),(result.impact.state.velocity-ep).cwiseAbs().maxCoeff(),(result.post.q-fq).cwiseAbs().maxCoeff(),(result.post.v-fv).cwiseAbs().maxCoeff()});if(error>=1e-12||event!=time+result.fractionTime||end!=time+h)throw std::runtime_error("factored transfer kernel changed original reference");
 auto old=ownedGeometry(s,q,result.old),plain=s.geometry(q);if((old.J.array()!=plain.J.array()).any()||(old.gap.array()!=plain.gap.array()).any())throw std::runtime_error("owned pullback changed old3 rows");for(unsigned f=0;f<3;++f)if((old.H[f].array()!=plain.H[f].array()).any())throw std::runtime_error("owned Hessian changed old3 rows");
 auto g=ownedGeometry(s,result.pre.q,result.all);double gradientError=0,hessianError=0;for(unsigned k=0;k<2;++k){Eigen::VectorXd d(n);for(unsigned i=0;i<n;++i)d(i)=std::sin(double((i+1)*(k+1)));d.normalize();d.tail<3>().setZero();double delta=1e-5;auto plus=ownedGeometry(s,result.pre.q+delta*d,result.all),minus=ownedGeometry(s,result.pre.q-delta*d,result.all);gradientError=std::max(gradientError,((plus.gap-minus.gap)/(2*delta)-g.J*d).cwiseAbs().maxCoeff());for(unsigned r=0;r<result.all.size();++r){Eigen::VectorXd fd=(plus.J.row(r)-minus.J.row(r)).transpose()/(2*delta),analytic=g.H[r]*d;hessianError=std::max(hessianError,(fd-analytic).norm()/std::max(1e-20,analytic.norm()));}}
 if(gradientError>1e-8||hessianError>1e-6)throw std::runtime_error("owned6-row directional derivative check failed");std::ofstream out(argv[3]);out<<std::setprecision(17)<<"reference_max_abs,event_time_s,gap_mm,linear_balance_Ns,angular_balance_Nmm_s,gradient_FD_abs,Hessian_directional_FD_relative\n"<<error<<','<<event<<','<<result.minimumGap<<','<<result.linearBalance<<','<<result.angularBalance<<','<<gradientError<<','<<hessianError<<'\n';std::cout<<"PASS factored isolated kernel exact reference and owned6-row directional derivatives;NOT SOFA/full objectivity or global CCD\n";
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
